document.addEventListener('focusin',event=>{const target=event.target.closest('[data-event],[data-session],[data-map-node]');if(target){hideMini();miniTarget=target;miniTimer=setTimeout(()=>previewMini(target),350);}});
document.addEventListener('focusout',hideMini);document.addEventListener('pointerdown',hideMini,true);document.addEventListener('scroll',hideMini,true);document.addEventListener('keydown',e=>{if(e.key==='Escape'){hideMini();if($('inspector-dialog').open&&!document.querySelector('dialog:modal'))$('inspector-dialog').close();}});

async function settingsRequest(path,options={}){const response=await fetch(path,{method:options.method||'GET',headers:options.body?{'content-type':'application/json'}:undefined,body:options.body?JSON.stringify(options.body):undefined,signal:options.signal?AbortSignal.any([options.signal,AbortSignal.timeout(15000)]):AbortSignal.timeout(15000),keepalive:path==='/api/settings/personal'});let data;try{data=await response.json();}catch{data={};}if(!response.ok)throw Object.assign(new Error(data.error||'Settings unavailable'),{status:response.status,errors:data.errors});if(path==='/api/settings'&&Number.isSafeInteger(data.personalRevision)){modernProfiles=true;profileRevision=data.personalRevision;}if(path==='/api/settings/personal'&&Number.isSafeInteger(data.revision))profileRevision=data.revision;return data;}
async function saveDisplay(){if(!displayReady||profileConflict)return;clearTimeout(saveTimer);saveTimer=null;if(displaySaving){displayDirty=true;return;}displaySaving=true;displayDirty=false;const sequence=++saveSequence,candidate=structuredClone(preferences);try{if(modernProfiles)await settingsRequest('/api/settings/personal',{method:'PUT',body:{revision:profileRevision,preferences:candidate}});else{const response=await fetch('/api/preferences',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(legacyPreferences(candidate)),keepalive:true});if(!response.ok)throw new Error('Profile unavailable');await response.json();}if(sequence===saveSequence)displaySaveState('Saved to your profile on the hub');}catch(e){if(e.status===409){profileConflict=true;displaySaveState('Another tab changed this profile · open settings to review');}else displaySaveState('Saved in this browser · hub save unavailable');}finally{displaySaving=false;if(displayDirty&&!profileConflict)queueDisplaySave();}}
function queueDisplaySave(){if(!displayReady||profileConflict)return;displaySaveState('Saving display profile…');clearTimeout(saveTimer);saveTimer=setTimeout(saveDisplay,400);}
async function initializeDisplay(){let remoteExists=false,remoteReached=false;try{try{const settings=await settingsRequest('/api/settings');preferences=normalizePreferences(settings.personal);remoteExists=true;remoteReached=true;}catch(e){if(e.status!==404&&e.status!==405)throw e;const response=await fetch('/api/preferences',{signal:AbortSignal.timeout(4000)});if(!response.ok)throw new Error('Profile unavailable');const saved=await response.json();remoteReached=true;remoteExists=saved.exists;if(saved.exists)preferences=normalizePreferences(saved.preferences);}displaySaveState(remoteExists?'Loaded your saved hub profile':'Preparing your display profile');}catch{displaySaveState('Using browser settings · hub profile unavailable');}applyPreferences(false);displayReady=true;if(remoteReached&&!remoteExists)queueDisplaySave();requestFrame();poll();}
window.addEventListener('pagehide',()=>{if(saveTimer)saveDisplay();});
for(const [selector,k] of [['.host-panel','fleetHeight'],['.inspector-panel','inspectorHeight'],['.attention-panel','attentionHeight']]){const element=document.querySelector(selector);new ResizeObserver(()=>{const height=parseFloat(element.style.height);if(displayReady&&Number.isFinite(height)&&Math.round(height)!==preferences[k]){preferences[k]=Math.round(height);try{localStorage.setItem('argellan-codex-display-v1',JSON.stringify(preferences));}catch{}queueDisplaySave();}}).observe(element);}

let mobileWorkspace;mobileWorkspace=mountMobileWorkspace({document,window,onViewChange(){paintInvalidated=timelineInvalidated=true;void renderScheduler.run(renderStages);requestFrame();}});

adaptiveViewport.addEventListener('change',()=>applyPreferences(false));
